import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';

ReactDOM.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
  document.getElementById('root')
);

import React, { useState, useEffect } from 'react';
import SplitPane from './components/SplitPane';
import Toolbar from './components/Toolbar';
import Editor from './components/Editor';
import Preview from './components/Preview';
import StatusBar from './components/StatusBar';
import { parseMarkdown } from './utils/markdownParser';
import { countWords, countCharacters } from './utils/countUtils';
import './styles/styles.css';

function App() {
  const [markdown, setMarkdown] = useState('');
  const [html, setHtml] = useState('');
  const [wordCount, setWordCount] = useState(0);
  const [charCount, setCharCount] = useState(0);

  useEffect(() => {
    const parsedHtml = parseMarkdown(markdown);
    setHtml(parsedHtml);
    setWordCount(countWords(markdown));
    setCharCount(countCharacters(markdown));
  }, [markdown]);

  const handleMarkdownChange = (newMarkdown) => {
    setMarkdown(newMarkdown);
  };

  const handleToolbarClick = (syntax) => {
    setMarkdown(prevMarkdown => prevMarkdown + syntax);
  };

  return (
    <div className="app-container">
      <Toolbar onButtonClick={handleToolbarClick} />
      <SplitPane>
        <Editor value={markdown} onChange={handleMarkdownChange} />
        <Preview html={html} />
      </SplitPane>
      <StatusBar wordCount={wordCount} charCount={charCount} />
    </div>
  );
}

export default App;

import React from 'react';
import './SplitPane.css';

function SplitPane({ children }) {
  return (
    <div className="split-pane-container">
      {children}
    </div>
  );
}

export default SplitPane;

.split-pane-container {
  display: flex;
  flex-grow: 1;
  overflow: hidden;
}

.split-pane-container > div {
  flex: 1;
  overflow-y: auto;
  padding: 15px;
  box-sizing: border-box;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .split-pane-container {
    flex-direction: column;
  }
  .split-pane-container > div {
    flex: none;
    width: 100%;
    height: 50%;
  }
}

import React from 'react';
import './Toolbar.css';

function Toolbar({ onButtonClick }) {
  const buttons = [
    { label: 'B', syntax: '**' },
    { label: 'I', syntax: '*' },
    { label: 'H1', syntax: '# ' },
    { label: 'H2', syntax: '## ' },
    { label: 'Code', syntax: '```\n' }
  ];

  return (
    <div className="toolbar">
      {buttons.map((button, index) => (
        <button
          key={index}
          onClick={() => onButtonClick(button.syntax)}
          className="toolbar-button"
        >
          {button.label}
        </button>
      ))}
    </div>
  );
}

export default Toolbar;

.toolbar {
  display: flex;
  padding: 10px;
  background-color: var(--background-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}

.toolbar-button {
  background-color: var(--button-background);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  padding: 8px 12px;
  margin-right: 5px;
  cursor: pointer;
  border-radius: 4px;
  font-weight: bold;
  transition: background-color 0.2s ease;
}

.toolbar-button:hover {
  background-color: var(--button-hover-background);
}

import React from 'react';
import './Editor.css';

function Editor({ value, onChange }) {
  const handleChange = (event) => {
    onChange(event.target.value);
  };

  return (
    <div className="editor-container">
      <textarea
        className="editor-textarea"
        value={value}
        onChange={handleChange}
        placeholder="Start writing your Markdown here..."
      />
    </div>
  );
}

export default Editor;

.editor-container {
  width: 100%;
  height: 100%;
}

.editor-textarea {
  width: 100%;
  height: 100%;
  padding: 15px;
  border: none;
  outline: none;
  resize: none;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  line-height: 1.6;
  background-color: var(--background-primary);
  color: var(--text-primary);
  box-sizing: border-box;
}

import React from 'react';
import './Preview.css';

function Preview({ html }) {
  return (
    <div className="preview-container">
      <div
        className="preview-content"
        dangerouslySetInnerHTML={{ __html: html }}
      />
    </div>
  );
}

export default Preview;

.preview-container {
  width: 100%;
  height: 100%;
  overflow-y: auto;
}

.preview-content {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  line-height: 1.7;
  color: var(--text-primary);
  background-color: var(--background-primary);
}

.preview-content h1, .preview-content h2, .preview-content h3 {
  color: var(--heading-color);
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}

.preview-content h1 {
  font-size: 2.2em;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.3em;
}

.preview-content h2 {
  font-size: 1.8em;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.3em;
}

.preview-content h3 {
  font-size: 1.5em;
}

.preview-content p {
  margin-bottom: 1em;
}

.preview-content a {
  color: var(--link-color);
  text-decoration: none;
}

.preview-content a:hover {
  text-decoration: underline;
}

.preview-content code {
  font-family: 'Courier New', Courier, monospace;
  background-color: var(--code-background);
  color: var(--code-color);
  padding: 0.2em 0.4em;
  border-radius: 3px;
  font-size: 0.9em;
}

.preview-content pre {
  background-color: var(--code-background);
  padding: 1em;
  border-radius: 5px;
  overflow-x: auto;
}

.preview-content pre code {
  background-color: transparent;
  color: var(--code-color);
  padding: 0;
  font-size: 0.95em;
}

.preview-content blockquote {
  border-left: 4px solid var(--border-color);
  padding-left: 1em;
  margin-left: 0;
  color: var(--blockquote-color);
  font-style: italic;
}

.preview-content ul, .preview-content ol {
  margin-bottom: 1em;
  padding-left: 2em;
}

.preview-content li {
  margin-bottom: 0.5em;
}

import React from 'react';
import './StatusBar.css';

function StatusBar({ wordCount, charCount }) {
  return (
    <div className="status-bar">
      <span className="status-item">Words: {wordCount}</span>
      <span className="status-item">Characters: {charCount}</span>
    </div>
  );
}

export default StatusBar;

.status-bar {
  display: flex;
  justify-content: flex-end;
  padding: 8px 15px;
  background-color: var(--background-secondary);
  color: var(--text-secondary);
  font-size: 0.9em;
  border-top: 1px solid var(--border-color);
  flex-shrink: 0;
}

.status-item {
  margin-left: 20px;
}

:root {
  /* Dark Theme Colors */
  --background-primary: #1e1e1e;
  --background-secondary: #252526;
  --text-primary: #d4d4d4;
  --text-secondary: #888888;
  --border-color: #444444;
  --button-background: #3a3a3a;
  --button-hover-background: #4a4a4a;
  --heading-color: #ffffff;
  --link-color: #00aaff;
  --code-background: #333333;
  --code-color: #ce9178;
  --blockquote-color: #888888;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--background-primary);
  color: var(--text-primary);
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

/* Basic Reset for HTML elements in preview */
h1, h2, h3, p, ul, ol, li, blockquote, code, pre, a {
  margin: 0;
  padding: 0;
}

import { marked } from 'marked';

// Configure marked.js for security and desired output
marked.setOptions({
  renderer: new marked.Renderer(),
  highlight: function (code, lang) {
    const hljs = require('highlight.js');
    const language = hljs.getLanguage(lang) ? lang : 'plaintext';
    return hljs.highlight(code, { language }).value;
  },
  langPrefix: 'hljs language-',
  pedantic: false,
  gfm: true,
  breaks: false,
  sanitize: true, // Important for security: removes HTML tags
  smartLists: true,
  smartypants: true,
  xhtml: false
});

export const parseMarkdown = (markdownText) => {
  if (!markdownText) {
    return '';
  }
  try {
    return marked.parse(markdownText);
  } catch (error) {
    console.error("Error parsing markdown:", error);
    return '<p>Error rendering markdown.</p>';
  }
};

export const countWords = (text) => {
  if (!text) {
    return 0;
  }
  const words = text.trim().split(/\s+/).filter(word => word.length > 0);
  return words.length;
};

export const countCharacters = (text) => {
  if (!text) {
    return 0;
  }
  return text.length;
};

import { parseMarkdown } from '../utils/markdownParser';

describe('markdownParser', () => {
  test('should parse basic bold markdown', () => {
    const markdown = '**bold text**';
    const expectedHtml = '<p><strong>bold text</strong></p>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should parse basic italic markdown', () => {
    const markdown = '*italic text*';
    const expectedHtml = '<p><em>italic text</em></p>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should parse H1 heading', () => {
    const markdown = '# Heading 1';
    const expectedHtml = '<h1>Heading 1</h1>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should parse H2 heading', () => {
    const markdown = '## Heading 2';
    const expectedHtml = '<h2>Heading 2</h2>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should parse code block', () => {
    const markdown = '```\nconsole.log("hello");\n```';
    const expectedHtml = '<pre><code class="language-plaintext">console.log(&quot;hello&quot;);\n</code></pre>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should parse mixed markdown', () => {
    const markdown = '# Title\n\nThis is a paragraph with **bold** and *italic* text.';
    const expectedHtml = '<h1>Title</h1><p>This is a paragraph with <strong>bold</strong> and <em>italic</em> text.</p>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });

  test('should return empty string for empty input', () => {
    expect(parseMarkdown('')).toBe('');
  });

  test('should handle null input gracefully', () => {
    expect(parseMarkdown(null)).toBe('');
  });

  test('should sanitize HTML tags', () => {
    const markdown = '<script>alert("XSS")</script>';
    const expectedHtml = '<p>&lt;script&gt;alert(&quot;XSS&quot;)&lt;/script&gt;</p>';
    expect(parseMarkdown(markdown)).toBe(expectedHtml);
  });
});

import { countWords, countCharacters } from '../utils/countUtils';

describe('countUtils', () => {
  describe('countWords', () => {
    test('should return 0 for empty string', () => {
      expect(countWords('')).toBe(0);
    });

    test('should return 0 for string with only whitespace', () => {
      expect(countWords('   \n  \t ')).toBe(0);
    });

    test('should count words correctly', () => {
      expect(countWords('Hello world')).toBe(2);
      expect(countWords('This is a test sentence.')).toBe(5);
      expect(countWords('One')).toBe(1);
    });

    test('should handle multiple spaces between words', () => {
      expect(countWords('Hello   world')).toBe(2);
    });

    test('should handle leading/trailing spaces', () => {
      expect(countWords('  Hello world  ')).toBe(2);
    });
  });

  describe('countCharacters', () => {
    test('should return 0 for empty string', () => {
      expect(countCharacters('')).toBe(0);
    });

    test('should count characters correctly', () => {
      expect(countCharacters('Hello world')).toBe(11);
      expect(countCharacters('Test')).toBe(4);
      expect(countCharacters('\n')).toBe(1);
    });

    test('should handle null input', () => {
      expect(countCharacters(null)).toBe(0);
    });
  });
});
